<?php
/** Renew ignored disposable browser credentials without printing cookie/nonce values. */
if(PHP_SAPI!=='cli')throw new RuntimeException('CLI required.');$site=getenv('TGIT_TEST_SITE_PATH');require $site.'/wp-load.php';if(!defined('TGIT_DISPOSABLE_TEST_SITE')||TGIT_DISPOSABLE_TEST_SITE!==true)throw new RuntimeException('Disposable environment required.');$file=dirname(__DIR__).'/tmp/journal-http-fixtures.json';$http=json_decode(file_get_contents($file),true,512,JSON_THROW_ON_ERROR);$http['sessions']=[];foreach(['owner'=>$http['owner'],'revoked'=>$http['viewer']]as$kind=>$user){wp_set_current_user($user);$expiry=time()+HOUR_IN_SECONDS;$token=WP_Session_Tokens::get_instance($user)->create($expiry);$cookie=wp_generate_auth_cookie($user,$expiry,'logged_in',$token);$auth=wp_generate_auth_cookie($user,$expiry,'auth',$token);$_COOKIE[LOGGED_IN_COOKIE]=$cookie;$http['sessions'][$kind]=['cookie_name'=>LOGGED_IN_COOKIE,'cookie_value'=>$cookie,'nonce'=>wp_create_nonce('wp_rest'),'auth_cookie_name'=>AUTH_COOKIE,'auth_cookie_value'=>$auth];}file_put_contents($file,json_encode($http));echo "PASS Disposable browser sessions refreshed without exposing credentials.\n";
